import ghidra.app.emulator.EmulatorHelper;import java.io.PrintWriter;
public class ZNativeResetOracle extends ZNativeWorldEffectOracle{
 int eh,events,starts,scenario;void event(int n){eh=(eh^n)*16777619;events++;}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){EmulatorHelper e=new EmulatorHelper(currentProgram);try{long G=O+1024,G2=G+72;for(long a:new long[]{RET,0x460910,0x452810,0x452960,0x458500,0x416270,0x44a900})e.setBreakpoint(toAddr(a));for(int s=0;s<4096;s++){scenario=s;calls=0;starts=0;events=0;eh=0x811c9dc5;e.writeMemory(toAddr(O),new byte[192]);e.writeMemory(toAddr(G),new byte[144]);put(e,0x632194,4,G);put(e,G+59,1,s%7==0?255:2);put(e,G2+59,1,s%11==0?255:3);put(e,O+0x7c,1,new int[]{0,1,2,3}[s%4]);put(e,O+0x5e,1,new int[]{-1,0,1}[s/4%3]);put(e,O+0x5c,1,new int[]{-128,-5,-1,0,5}[s/12%5]);put(e,O+0x14,4,s/60%2);put(e,O+4,1,new int[]{-1,0,20,127}[s/120%4]);e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",O);if(!e.run(toAddr(0x44cac0),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==0x460910){e.writeRegister("EAX",(s*7919^(calls++)*2027)&0xffffffffL);}else if(pc==0x452810){event(10+starts);e.writeRegister("EAX",(s/480%2==0?1:0));if(starts++==1&&(s&1)!=0)put(e,0x632194,4,G2);}else if(pc==0x452960){event(20);e.writeRegister("EAX",new int[]{1,2,3}[s/960%3]);}else if(pc==0x458500){event(30);e.writeRegister("EAX",new int[]{0xffff,0x0000,0x010a,0x01ff}[s/240%4]);}else if(pc==0x416270){event(40);e.writeRegister("EAX",s/1920%2);}else if(pc==0x44a900){event(50+(e.readRegister("EDX").intValue()&255));}else throw new Exception("Unexpected");long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}out.println("{\"scenario\":"+s+",\"order\":"+read(e,O+0x5c,1)+",\"first\":"+read(e,G+59,1)+",\"second\":"+read(e,G2+59,1)+",\"rng\":"+calls+",\"events\":"+events+",\"eventHash\":"+(eh&0xffffffffL)+"}");}}finally{e.dispose();}}}
}
